import sys
from collections import deque
def f(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    q=deque()
    # flood from border through non-8 cells
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]!=8 and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]!=8 and not seen[i][j]: seen[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and not seen[ni][nj] and g[ni][nj]!=8:
                seen[ni][nj]=True;q.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=8: out[i][j]=2
    return out
