import itertools
def struct(inp,i,j,H,W):
    # distances to nearest wall (or None=edge) in 4 dirs, and whether wall is exactly adjacent
    def dist(i0,j0,a,b):
        d=1
        while True:
            ni,nj=i0+a,j0+b
            if not(0<=ni<H and 0<=nj<W): return None
            if inp[ni][nj]==8: return d
            d+=1
    L=dist(i,j,0,-1); R=dist(i,j,0,1); U=dist(i,j,-1,0); D=dist(i,j,1,0)
    return (L,R,U,D)
